-- Puntaje: Dell premium sin resta, +5 si incluye cargador, ThinkBook reconocida.
--
-- Caso real: una ThinkBook 15 G2 (Ryzen 7 4700U, 16GB, $199, "Power Supply:
-- Included") sacaba 61 y no avisaba. Con esto saca 74.
-- - Dell Latitude 7000/9000, XPS y Precision: escalafón 0.85 (como EliteBook)
--   y sin los -10 de "Latitude". Las Latitude 3000/5000 siguen igual.
-- - "Incluye cargador": +5 (penalización negativa). No cuenta "No AC
--   adapter", "Charger Included: No" ni "si sale en la foto".
-- - Lenovo ThinkBook: escalafón 0.7 (antes caía al valor de respaldo, 0.25).
-- modelTiers y scorePenalties de la fila eran iguales a los del código; se
-- reemplazan enteros por los del código (generados, no tipeados a mano).

update public.search_config
   set config = jsonb_set(jsonb_set(config, '{modelTiers}', $j$[{"label":"Dell premium (Latitude 7000/9000, XPS, Precision)","pattern":"\\bxps\\b|\\bprecision\\b|\\blatitude[\\s-]*(?:\\d{1,2}(?:\\.\\d)?\\s*(?:\"|”|''|in(?:ch)?|-inch)?\\s*)?e?[79]\\d{3}\\b","flags":"i","weight":0.85},{"label":"ThinkPad T / X / P","pattern":"thinkpad\\s*[txp]\\d|thinkpad\\s*x1","flags":"i","weight":1},{"label":"ThinkPad (cualquier línea)","pattern":"thinkpad|think\\s*pad","flags":"i","weight":0.95},{"label":"HP EliteBook / ZBook","pattern":"elitebook|zbook","flags":"i","weight":0.85},{"label":"Dynabook Portégé / Tecra","pattern":"port[ée]g[ée]|portege|dynabook|tecra","flags":"i","weight":0.8},{"label":"Lenovo ThinkBook","pattern":"think\\s*book","flags":"i","weight":0.7},{"label":"HP ProBook","pattern":"probook","flags":"i","weight":0.68},{"label":"Dell Precision / Surface Laptop","pattern":"precision|surface\\s*laptop","flags":"i","weight":0.55},{"label":"Dell Latitude","pattern":"latitude","flags":"i","weight":0.5}]$j$::jsonb), '{scorePenalties}', $j$[{"label":"Dell Latitude","pattern":"\\blatitude\\b(?![\\s-]*(?:\\d{1,2}(?:\\.\\d)?\\s*(?:\"|”|''|in(?:ch)?|-inch)?\\s*)?e?[79]\\d{3}\\b)","flags":"i","points":10,"scope":"title","ignoreNegated":false},{"label":"Incluye cargador","pattern":"(?:\\b(?:includes?|including|included|comes\\s+with|ships\\s+with|with)\\b|w\\/|\\+)\\s*(?:(?:an?|the|original|oem|genuine)\\s+)*(?:ac\\s*|power\\s*)?(?:adapter|charger|power\\s*(?:supply|cord|cable))s?\\b|\\b(?:ac\\s*adapter|power\\s*adapter|charger|power\\s*supply|power\\s*cord)s?\\s*(?:is\\s*|are\\s*)?(?:[:\\-]\\s*)?(?:included|yes)\\b(?!\\s*[:\\-]?\\s*(?:no|not|n\\/a)\\b)","flags":"i","points":-5,"scope":"titleAndDescription","ignoreNegated":true,"ignoreContextPattern":"\\bif\\b|unless|\\bmay\\b|optional|sold\\s+separately|not\\s+included|purchase|available|upgrade|add-?on"},{"label":"Componente con falla","pattern":"\\b(?:ports?|usb(?:[\\s-]?[ac])?|webcam|camera|cam|speakers?|audio|sound|mic(?:rophone)?|bluetooth|wi-?fi|wireless|fingerprint|reader|touch\\s*screen|touchscreen|touch|trackpad|touchpad|mouse|clicks?|keys?|keyboard|backlight|stylus|pen|buttons?|jack|hdmi|ethernet|lan|sd|card|fan|led|lights?|sensor|nfc|sim|lte|wwan|display\\s*port|screws?|covers?|feet|foot|rubber|latch)\\b(?:[^.!?\\n|•]|\\.(?=\\d)){0,40}?\\b(?:not\\s*working|(?:does\\s*not|doesn'?t|won'?t)\\s*work|non[\\s-]?functional|inoperable)\\b","flags":"i","points":10,"scope":"titleAndDescription","ignoreNegated":true,"ignoreContextPattern":"return|refund|warrant|guarant|polic|listed\\s+as|label|exclud|exception|unless|\\bif\\b|\\bmay\\b|\\bshould\\b|buyer|grade[sd]?\\b|definition|not\\s+tested|untested|focus\\s+materials|\\bwe\\s+(?:will|do|are|can)|contact|as\\s+described"},{"label":"Declara daño","pattern":"\\b(?:dmg|damaged?)\\b","flags":"i","points":10,"scope":"titleAndDescription","ignoreNegated":true,"ignoreContextPattern":"ship|transit|package|parcel|carrier|\\bups\\b|fedex|usps|deliver|return|refund|claim|tamper|arriv|not as (?:described|shown)|warranty|misuse|abuse|accident|avoid|any signs of|materials recovery|sanitized|latches, hinges|used (?:excellent|fair|poor)|new open box"}]$j$::jsonb)
 where id = 1;
